function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 's needs 1 to 100 characters.';
  for (let i = 0; i < s.length; i++) {
    if (i % 2 === 0 && !/[a-z]/.test(s[i])) return 'Even positions of s must be lowercase letters.';
    if (i % 2 === 1 && !/[0-9]/.test(s[i])) return 'Odd positions of s must be digits.';
    if (i % 2 === 1 && s.charCodeAt(i - 1) + Number(s[i]) > 122) return 'A shift may not go past the letter z.';
  }
  return null;
}

