function replaceDigits(s) {
  const result = [];

  for (let i = 0; i < s.length; i++) {
    if (i % 2 === 0) {
      result.push(s[i]);
    } else {
      const base = s.charCodeAt(i - 1);
      const offset = Number(s[i]);
      result.push(String.fromCharCode(base + offset));
    }
  }
  return result.join('');
}

