function replaceDigits(s) {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  let out = '';
  for (let i = 0; i < s.length; i += 2) {
    out += s[i];
    if (i + 1 < s.length) {
      out += alphabet[alphabet.indexOf(s[i]) + parseInt(s[i + 1], 10)];
    }
  }
  return out;
}

