function generate(rand, size) {
  const length = size === 'large' ? 99 + Math.floor(rand() * 2) : 1 + Math.floor(rand() * 9);
  const narrow = size === 'small' && rand() < 0.4;
  let s = '';
  for (let i = 0; i < length; i++) {
    if (i % 2 === 0) {
      const index = narrow ? 17 + Math.floor(rand() * 9) : Math.floor(rand() * 26);
      s += String.fromCharCode(97 + index);
    } else {
      const room = Math.min(9, 122 - s.charCodeAt(i - 1));
      s += String(Math.floor(rand() * (room + 1)));
    }
  }
  return [s];
}
